/* Font utility classes */
@source inline("font-heading");
@source inline("font-display");

/* Transition classes */
@source inline("transition-colors");
@source inline("transition-all");
@source inline("duration-300");
@source inline("ease-in-out");

/* Custom utilities */
@utilities {
	.scrollbar-hide {
		-ms-overflow-style: none;
		scrollbar-width: none;
	}
	.scrollbar-hide::-webkit-scrollbar {
		display: none;
	}
	.font-heading {
		font-family: var(--font-heading);
	}
	.font-display {
		font-family: var(--font-display);
	}
}

* {
	box-sizing: border-box;
}

/* Global Typography Styles */
h1, h2, h3, h4, h5, h6 {
	font-family: 'Droid Serif', Georgia, serif;
	@apply font-medium;
}

h1 {
	@apply text-4xl md:text-5xl lg:text-5xl;
}

h2 {
	@apply text-3xl md:text-4xl lg:text-4xl;
}

h3 {
	@apply text-2xl md:text-3xl lg:text-3xl;
}

h4 {
	@apply text-xl md:text-2xl lg:text-2xl;
}

h5 {
	@apply text-lg md:text-xl lg:text-xl;
}

h6 {
	@apply text-base md:text-lg lg:text-lg;
}

/* Body text styling */
body {
	@apply font-sans text-base leading-relaxed;
}

/* Code text styling */
code, pre {
	@apply font-mono;
}

input, textarea {
	@apply focus:outline-none;
}

/* Override input field border radius to be more square while keeping buttons pill-shaped */
.input, .textarea {
	border-radius: 0.5rem !important;
}

/* Fix focus styling to prevent double borders and use orange color with 75% opacity */
.input:focus, 
.input:focus-within, 
.textarea:focus, 
.textarea:focus-within,
select:focus, 
.select:focus, 
.select:focus-within,
.dropdown:focus,
.dropdown:focus-within,
[role="listbox"]:focus, 
[role="combobox"]:focus,
.dropdown-content:focus,
ul[role="listbox"]:focus {
	border-color: rgba(247, 147, 26, 0.75) !important;
	
	outline: none !important;
}


/* Glow animations */
@keyframes pulse-glow {

	0%,
	100% {
		opacity: 0.4;
	}

	50% {
		opacity: 0.7;
	}
}

@keyframes float-glow {
	0% {
		transform: translateY(0) translateX(0);
	}

	33% {
		transform: translateY(-8px) translateX(8px);
	}

	66% {
		transform: translateY(4px) translateX(-4px);
	}

	100% {
		transform: translateY(0) translateX(0);
	}
}

.glow-effect {
	position: relative;
	overflow: hidden;
	isolation: isolate;
}

.glow-container {
	position: absolute;
	inset: 0;
	z-index: -1;
	overflow: hidden;
	pointer-events: none;
}

.glow-blur {
	position: absolute;
	border-radius: 100%;
	filter: blur(100px);
	opacity: 0.4;
	animation:
		pulse-glow 5s infinite ease-in-out,
		float-glow 20s infinite ease-in-out;
}

.glow-primary {
	background-color: var(--color-primary);
}

.glow-secondary {
	background-color: var(--color-secondary);
}

.glow-accent {
	background-color: var(--color-accent);
}

/* Dark mode specific adjustments */
:root[data-theme='dark'] .glow-blur {
	opacity: 0.15;
	filter: blur(120px);
}

/* Light mode adjustments */
:root[data-theme='light'] .glow-blur {
	opacity: 0.2;
	filter: blur(100px);
}

::view-transition-old(root),
::view-transition-new(root) {
	animation-duration: 500ms;
}


body {
	@apply text-gray-900 dark:text-gray-100;
	background-color: var(--color-base-300);
}


/* 
 * Mobile Layout Utilities
 * These utilities help with mobile-first responsive layouts
 */

/* Use dvh (dynamic viewport height) when supported */
@supports (height: 100dvh) {
	.min-h-screen {
		min-height: 100dvh;
	}

	.max-h-screen {
		max-height: 100dvh;
	}

	.h-screen {
		height: 100dvh;
	}
}

/* Fallback for browsers that don't support dvh */
@supports not (height: 100dvh) {
	.min-h-screen {
		min-height: 100vh;
	}

	.max-h-screen {
		max-height: 100vh;
	}

	.h-screen {
		height: 100vh;
	}
}

/* Safe area insets for notched devices */
.pt-safe {
	padding-top: env(safe-area-inset-top, 0);
}

.pb-safe {
	padding-bottom: env(safe-area-inset-bottom, 0);
}

.pl-safe {
	padding-left: env(safe-area-inset-left, 0);
}

.pr-safe {
	padding-right: env(safe-area-inset-right, 0);
}

/* CSS Custom Properties for bottom navigation */
:root {
	--bottom-nav-height: 80px;
	--bottom-nav-height-safe: calc(80px + env(safe-area-inset-bottom, 0));
}

/* Bottom navigation bar spacing - removed body padding since layout handles this */
@media (max-width: 1024px) {
	body {
		box-sizing: border-box;
		width: 100vw;
		overflow-x: hidden; /* Prevent horizontal scrollbars */
	}
	
	/* Ensure main content doesn't overflow */
	main {
		max-width: 100vw;
		overflow-x: hidden;
	}
}

/* Additional spacing for devices with safe area insets - removed body padding */
@media (max-width: 1024px) and (min-height: 600px) {
	body {
		box-sizing: border-box;
		width: 100vw;
		overflow-x: hidden; /* Prevent horizontal scrollbars */
	}
}

/* Bottom navigation dock styles - common styles shared across app */
.menu-active {
	@apply bg-primary/10 text-primary font-semibold;
}

.dock-active {
	@apply relative;
}

/* Base state for all navigation buttons */
.dock a {
	position: relative;
}

.dock a::after {
	content: '';
	position: absolute;
	bottom: -2px;
	left: 50%;
	transform: translateX(-50%);
	width: 0px;
	height: 2px;
	border-radius: 1px;
	background-color: currentColor;
	z-index: 10;
	transition: width 0.3s ease-out, opacity 0.3s ease-out;
	opacity: 0;
}

/* Active state - expands the indicator */
.dock a.dock-active::after {
	width: 20px;
	opacity: 1;
}

/* Scrollbar styling for webkit browsers */
::-webkit-scrollbar {
	width: 6px;
	height: 6px;
}

::-webkit-scrollbar-track {
	background: transparent;
}

::-webkit-scrollbar-thumb {
	background: rgba(127, 127, 127, 0.5);
	border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
	background: rgba(127, 127, 127, .7);
}

/* Hide scrollbars on mobile devices but keep functionality */
@media (max-width: 768px) {
	.hide-scrollbar {
		scrollbar-width: none;
		/* Firefox */
		-ms-overflow-style: none;
		/* IE/Edge */
	}

	.hide-scrollbar::-webkit-scrollbar {
		display: none;
		/* Chrome, Safari, Opera */
	}
}

/* Prevent horizontal scrollbars on mobile */
@media (max-width: 1024px) {
	.no-horizontal-scroll {
		overflow-x: hidden;
		max-width: 100vw;
	}
	
	/* Ensure containers don't cause horizontal scroll */
	.container {
		max-width: 100vw;
		overflow-x: hidden;
	}
}
